import{_ as t,o as a,c as n,a6 as s}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Organiser les automatisations","description":"","frontmatter":{"title":"Organiser les automatisations","docId":"user.automations.index","translationKey":"user.automations.index","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"33d5d9aa4db49a70a3b416ea817479822f06d7cb028699ab9bd344c14cd79892","translationRevision":"d70b4d5c76c5095a0877c77861d4e6a10267c17f2df8d19a3b0660a398995d5e","order":10},"headers":[],"relativePath":"fr/user/automations/index.md","filePath":"fr/user/automations/index.md","lastUpdated":1794611623000}'),i={name:"fr/user/automations/index.md"};function r(o,e,l,u,d,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="organize-automations" tabindex="-1">Organiser les automatisations <a class="header-anchor" href="#organize-automations" aria-label="Permalink to &quot;Organiser les automatisations {#organize-automations}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Construire une petite bibliothèque compréhensible qui réagit aux événements LIVE. Il faut un hôte de bureau fonctionnel. Une véritable <a href="./../live/connections.html">connexion LIVE</a> est nécessaire pour valider les événements distants ; les actions de plugins nécessitent aussi un plugin et un service prêts.</p><h2 id="understand-the-library" tabindex="-1">Comprendre la bibliothèque <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to &quot;Comprendre la bibliothèque {#understand-the-library}&quot;">​</a></h2><p>Une <strong>Action</strong> est une opération configurée réutilisable, comme écrire une ligne de journal ou jouer un son. Un <strong>Event</strong> choisit un déclencheur, des filtres, un délai et des actions liées. Un profil regroupe les définitions d’un usage ; un seul ensemble de profil est actif à la fois. Les <a href="./variables.html">Variables</a> d’exécution fournissent des valeurs réutilisables par plusieurs actions.</p><ol><li>Ouvrez <strong>Automations</strong> et confirmez le profil actif avant toute modification. Recherchez séparément dans Events et Actions pour savoir quel type d’enregistrement vous sélectionnez.</li><li>Commencez par la <a href="./first-rule.html">première règle de journalisation</a>. Créez son action, puis un événement qui la référence.</li><li>Choisissez un déclencheur pris en charge par l’hôte actuel. Utilisez le sélecteur de champs pour ajouter des filtres adaptés. Plusieurs conditions restreignent les correspondances ; elles ne modifient pas la charge utile entrante.</li><li>Définissez un délai et sa portée. Un délai global limite la règle pour tous les spectateurs ; un délai par utilisateur suit chaque spectateur séparément.</li><li>Reliez les actions voulues dans l’ordre. Le mode normal exécute la liste choisie ; le mode aléatoire y sélectionne une action. Une action de délai reporte les actions suivantes sans ralentir l’ingestion LIVE.</li><li>Enregistrez, examinez les changements de définition affichés, puis activez explicitement les enregistrements à exécuter. Consultez l’historique pour le nom de l’action, son résultat et son erreur.</li></ol><p>Les tests peuvent exécuter les effets configurés. Lisez la liste d’actions sélectionnée avant d’appuyer sur <strong>Test</strong> ou de déclencher un événement, surtout pour l’audio, HTTP, les points et les opérations de plugins. Utilisez la journalisation pendant l’apprentissage.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>L’édition locale, l’exécution, les modèles, les profils et l’historique sont disponibles. Les déclencheurs de plugins apparaissent uniquement lorsque le plugin correspondant est installé et activé. L’activation dépend de la surface et des valeurs enabled examinées ; vérifiez événements et actions avant confirmation. Le panneau <strong>Changes</strong> de Events/Actions est une <a href="./../cloud/changes.html">comparaison de référence locale</a>, pas un téléversement automatique vers Cloud.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>En l’absence d’exécution, vérifiez dans cet ordre le profil actif, les états d’activation, le déclencheur, les filtres, le délai et les actions manquantes. En cas de conflit de révision, lisez la définition actuellement enregistrée et examinez-la à nouveau. N’écrasez pas aveuglément la mise à jour d’une autre personne. Exportez un <a href="./templates.html">profil</a> fonctionnel avant des modifications étendues.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Avant import ou changement de profil, lisez <a href="./templates.html#operational-details">l’activation par surface</a>. Le changement peut réactiver des membres désactivés individuellement. Le cooldown est en mémoire, limité à 24 heures ; les spectateurs sans uniqueId partagent un contexte anonyme. À 8 192 clés conservées, la table est vidée : surcharge ou redémarrage peuvent autoriser des exécutions supplémentaires. Ce n’est ni quota durable ni garantie de replay.</p>',13)])])}const h=t(i,[["render",r]]);export{m as __pageData,h as default};
